class SK_API SkCodec : SkNoncopyable {
public:
    static constexpr size_t MinBufferedBytesNeeded() { return 32; }
    enum Result {
        kSuccess,
        kIncompleteInput,
        kErrorInInput,
        kInvalidConversion,
        kInvalidScale,
        kInvalidParameters,
        kInvalidInput,
        kCouldNotRewind,
        kInternalError,
        kUnimplemented,
        kOutOfMemory,
    };
    static const char* ResultToString(Result);
    enum class SelectionPolicy { kPreferStillImage, kPreferAnimation, };
    static std::unique_ptr<SkCodec> MakeFromStream(
            std::unique_ptr<SkStream>,
            SkSpan<const SkCodecs::Decoder> decoders,
            Result* = nullptr,
            SkPngChunkReader* = nullptr,
            SelectionPolicy selectionPolicy = SelectionPolicy::kPreferStillImage);
    static std::unique_ptr<SkCodec> MakeFromStream(
            std::unique_ptr<SkStream>,
            Result* = nullptr,
            SkPngChunkReader* = nullptr,
            SelectionPolicy selectionPolicy = SelectionPolicy::kPreferStillImage);
    static std::unique_ptr<SkCodec> MakeFromData(sk_sp<const SkData>,
                                                 SkSpan<const SkCodecs::Decoder> decoders,
                                                 SkPngChunkReader* = nullptr);
    static std::unique_ptr<SkCodec> MakeFromData(sk_sp<const SkData>, SkPngChunkReader* = nullptr);
    virtual ~SkCodec();
    SkImageInfo getInfo() const { return fEncodedInfo.makeImageInfo(); }
    SkISize dimensions() const { return {fEncodedInfo.width(), fEncodedInfo.height()}; }
    SkIRect bounds() const {
        return SkIRect::MakeWH(fEncodedInfo.width(), fEncodedInfo.height());
    }
    const skcms_ICCProfile* getICCProfile() const { return this->getEncodedInfo().profile(); }
    const skhdr::Metadata& getHdrMetadata() const { return fEncodedInfo.getHdrMetadata(); }
    bool hasHighBitDepthEncodedData() const { return this->getEncodedInfo().bitsPerComponent() >= 16; }
    SkEncodedOrigin getOrigin() const { return fOrigin; }
    SkISize getScaledDimensions(float desiredScale) const {
        SkASSERT(desiredScale > 0.0f);
        if (desiredScale <= 0.0f) { return SkISize::Make(0, 0); }
        if (desiredScale >= 1.0f) { return this->dimensions(); }
        return this->onGetScaledDimensions(desiredScale);
    }
    bool getValidSubset(SkIRect* desiredSubset) const { return this->onGetValidSubset(desiredSubset); }
    SkEncodedImageFormat getEncodedFormat() const { return this->onGetEncodedFormat(); }
    virtual std::unique_ptr<SkStream> getEncodedData() const;
    enum ZeroInitialized { kYes_ZeroInitialized, kNo_ZeroInitialized, };
    struct Options {
        Options()
                : fZeroInitialized(kNo_ZeroInitialized)
                , fSubset(nullptr)
                , fFrameIndex(0)
                , fPriorFrame(kNoFrame)
                , fMaxDecodeMemory(0) {}
        ZeroInitialized fZeroInitialized;
        const SkIRect* fSubset;
        int fFrameIndex;
        int fPriorFrame;
        size_t fMaxDecodeMemory;
    };
    Result getPixels(const SkImageInfo& info, void* pixels, size_t rowBytes, const Options*);
    Result getPixels(const SkImageInfo& info, void* pixels, size_t rowBytes) {
        return this->getPixels(info, pixels, rowBytes, nullptr);
    }
    Result getPixels(const SkPixmap& pm, const Options* opts = nullptr) {
        return this->getPixels(pm.info(), pm.writable_addr(), pm.rowBytes(), opts);
    }
    std::tuple<sk_sp<SkImage>, SkCodec::Result> getImage(const SkImageInfo& info,
                                                         const Options* opts = nullptr);
    std::tuple<sk_sp<SkImage>, SkCodec::Result> getImage();
    bool queryYUVAInfo(const SkYUVAPixmapInfo::SupportedDataTypes& supportedDataTypes,
                       SkYUVAPixmapInfo* yuvaPixmapInfo) const;
    Result getYUVAPlanes(const SkYUVAPixmaps& yuvaPixmaps);
    Result startIncrementalDecode(const SkImageInfo& dstInfo, void* dst, size_t rowBytes,
            const Options*);
    Result startIncrementalDecode(const SkImageInfo& dstInfo, void* dst, size_t rowBytes) {
        return this->startIncrementalDecode(dstInfo, dst, rowBytes, nullptr);
    }
    Result incrementalDecode(int* rowsDecoded = nullptr) {
        if (!fStartedIncrementalDecode) { return kInvalidParameters; }
        return this->onIncrementalDecode(rowsDecoded);
    }
    Result startScanlineDecode(const SkImageInfo& dstInfo, const Options* options);
    Result startScanlineDecode(const SkImageInfo& dstInfo) { return this->startScanlineDecode(dstInfo, nullptr); }
    int getScanlines(void* dst, int countLines, size_t rowBytes);
    bool skipScanlines(int countLines);
    enum SkScanlineOrder { kTopDown_SkScanlineOrder, kBottomUp_SkScanlineOrder, };
