// Create a minimal, self-contained rewindable/seekable memory stream that does not
// depend on external Skia link-time symbols. This satisfies downstream SkStream APIs
// like read/peek/seek/duplicate/fork used by other stubs.

class FuzzMemoryStream final : public SkStreamAsset {
public:
    FuzzMemoryStream(std::string data)
        : fStorage(std::move(data)), fPos(0) {}

    // SkStream overrides
    size_t read(void* buffer, size_t size) override {
        if (size == 0) return 0;
        size_t remaining = (fPos < fStorage.size()) ? (fStorage.size() - fPos) : 0;
        size_t n = size < remaining ? size : remaining;
        if (buffer && n) { memcpy(buffer, fStorage.data() + fPos, n); }
        fPos += n;
        return n;
    }
    bool isAtEnd() const override {
        return fPos >= fStorage.size();
    }

    // SkStream (optional) peek; does not advance position
    size_t peek(void* buffer, size_t size) const override {
        if (!buffer || size == 0) return 0;
        size_t remaining = (fPos < fStorage.size()) ? (fStorage.size() - fPos) : 0;
        size_t n = size < remaining ? size : remaining;
        if (n) { memcpy(buffer, fStorage.data() + fPos, n); }
        return n;
    }

    // SkStreamRewindable override
    bool rewind() override { fPos = 0; return true; }

    // SkStreamSeekable overrides
    size_t getPosition() const override { return fPos; }
    bool seek(size_t position) override {
        if (position > fStorage.size()) { fPos = fStorage.size(); return false; }
        fPos = position; return true;
    }
    bool move(long offset) override {
        // Clamp to [0, size]
        long long target = (long long)fPos + (long long)offset;
        if (target < 0) target = 0;
        size_t newPos = (size_t)((target > (long long)fStorage.size()) ? fStorage.size() : target);
        bool ok = (newPos == (size_t)target);
        fPos = newPos; return ok;
    }

    // SkStreamAsset overrides
    bool hasLength() const override { return true; }
    size_t getLength() const override { return fStorage.size(); }

    const void* getMemoryBase() override { return fStorage.data(); }

private:
    // duplication/forking create new streams sharing/copying the same data
    SkStreamAsset* onDuplicate() const override {
        return new FuzzMemoryStream(fStorage); // duplicate starts at position 0
    }
    SkStreamAsset* onFork() const override {
        FuzzMemoryStream* s = new FuzzMemoryStream(fStorage);
        s->fPos = fPos; // fork preserves current position
        return s;
    }

    std::string fStorage;
    size_t      fPos;
};

